// asked anything about it. Each is a whole constant rather than a
// sentence built around a value, and each ends the reading: an answer
// that did not parse has no members to judge.
const ANSWER_FAULTS = {
  noAnswer: 'the call came back with no answer',
  notText: 'the answer is not text',
  tooLong: 'the answer is longer than this node reads',
  notJson: 'the answer is not JSON',
};

