// rather than from this body, so it carries a prototype, and a
// hasOwn read is what keeps an inherited member from standing in for
// one the node never stated. research-brief.ts spliced above makes
// the same reading of the answer's own members and declares its own
// helper for it; this one is about the item, not about the answer.
function itemMember(source, name) {
  return Object.hasOwn(source, name)
    ? source[name]
    : undefined;
}

