// reading. Read in the order the members actually arrive in: a
// completed call answers text, and a call that did not complete
// answers an error member instead, Research Candidate declaring
// onError continueRegularOutput so that a failure is still an item
// and the position below it still lines up.
function answerText(answer) {
  const text = itemMember(answer, 'text');

  if (typeof text !== 'string') {
    return {
      text: '',
      fault: Object.hasOwn(answer, 'error')
        ? ANSWER_FAULTS.noAnswer
        : ANSWER_FAULTS.notText,
    };
  }

  return text.length > MAX_ANSWER_CHARS
    ? { text: '', fault: ANSWER_FAULTS.tooLong }
    : { text, fault: '' };
}

// The answer with its fence taken off, where it wore one. The opening
// line goes whole, that line carrying the language a model names its
// own answer with, and everything from the last fence on goes with
// it. A fence with no line break after it and a fence never closed
// are both left as they stand: neither is a shape this can repair,
// and the parse below reports it.
function unfenced(text) {
  const trimmed = text.trim();

  if (!trimmed.startsWith(ANSWER_FENCE)) {
    return trimmed;
  }

  const opened = trimmed.indexOf('\n');
  const closed = trimmed.lastIndexOf(ANSWER_FENCE);

  if (opened === -1) {
    return trimmed;
  }

  return closed > opened
    ? trimmed.slice(opened + 1, closed).trim()
    : trimmed.slice(opened + 1).trim();
}

// What the model came back with, as a value or as the sentence saying
// why there is none. Never both. The parse is the whole of what this
// does — every rule about what the value HOLDS is the spliced
// library's, and asking it about a string would be asking it the
// wrong question.
function parsedAnswer(answer) {
  const carried = answerText(answer);

  if (carried.fault !== '') {
    return { value: null, fault: carried.fault };
  }

  try {
    return { value: JSON.parse(unfenced(carried.text)), fault: '' };
  } catch {
    return { value: null, fault: ANSWER_FAULTS.notJson };
  }
}

// What a candidate carries onward when nothing is recorded about it.
// The four ids travel whatever happened, because the group that
// closes this pass is charged to the run and reads its counts off
// what came through here, and the statement below needs the pool row
// it did not stamp to be nameable. Exactly one of the record members
// is ever set: a summary and a payload, or a reason.
function refused(row, reason) {
  return {
    json: {
      run_id: row.run_id,
      pool_id: row.pool_id,
      domain_id: row.domain_id,
      entity_id: row.entity_id,
      research_summary: null,
      research_payload: null,
      research_refusal: reason,
    },
  };
