const ledger = $input.all();
const answers = $('Research Candidate').all();

// Held against each other before either is read. Both lists are one
// item per call by construction, the ledger statement answering one
// row whatever it wrote and the chain node answering one item
// whatever came back, so a length that differs is a canvas that has
// stopped meaning what this node reads it to mean.
if (ledger.length !== answers.length) {
  throw new Error(
    '[ar-research] Judge Research Answer cannot pair '
    + String(ledger.length) + ' ledger rows against '
    + String(answers.length) + ' answers: the two are paired by '
    + 'position and a difference between them files one candidate '
    + 'research under another candidate',
  );
}

return ledger.map((item, index) => {
  const row = item.json;
  const read = parsedAnswer(answers[index].json);

  if (read.fault !== '') {
    return refused(row, read.fault);
  }

  // The judgement, and the offered set it is made against is the one
  // Prepare Model Prompt derived and the ledger carried here. A list
  // that is not a list offers nothing, which is the library's own
  // fail-closed reading and refuses every citation rather than
  // accepting every citation.
  const faults = researchBriefErrors(read.value, row.offered_ids);

  if (faults.length > 0) {
    return refused(row, faults.join(REFUSAL_JOIN));
  }

  const record = composeResearchRecord(read.value);

  // The reduction, and the last thing that happens to this text
  // before a column holds it. sanitizeUntrusted keeps every word in
  // order and bounds what the text can DO, so what is stored still
  // says what the model said and can no longer act on a reader that
  // renders it.
  //
  // A reduction that empties a summary stores the empty string
  // rather than a null, and the two are different states rather than
  // a distinction nobody acts on. entity_research.summary says a
  // NULL means no prose was produced; here prose was produced, was
  // judged non-empty, and was entirely active markup. Storing a NULL
  // would file it with the passes that answered structure alone.
  return {
    json: {
      run_id: row.run_id,
      pool_id: row.pool_id,
      domain_id: row.domain_id,
      entity_id: row.entity_id,
      research_summary: sanitizeUntrusted(record.summary),
      research_payload: record.payload,
      research_refusal: null,
    },
  };
});

